function addDiffTargetPath(add, line) {
    var m = line.match(/^--- (?:(?:a\/)?(.+))$/);
    if (m && m[1] !== '/dev/null') {
        add(m[1]);
        return;
    }
    m = line.match(/^\+\+\+ (?:(?:b\/)?(.+))$/);
    if (m && m[1] !== '/dev/null') {
        add(m[1]);
    }
}

