function parseDiffPaths(diffText) {
    if (!diffText) return [];
    var seen = {};
    var out = [];
    var add = function(p) {
        var n = normalizePath(p);
        if (!n || seen[n]) return;
        seen[n] = true;
        out.push(n);
    };
