    // file) may contribute paths — a CONTENT line whose text starts with
    // "++ "/"-- " renders as "+++ "/"--- " and must not join the set
    // (thread PRT_kwDORYAuYs6uJ04O: phantom owned files over-match).
    var headerZone = true;
